 12  /** Quiet, structural placeholder for "nothing here yet". */
 13  export function EmptyState({
 14    title,
 15    hint,
 16    actions,
 17  }: {
 18    title: string;
 19    hint?: string;
 20    actions?: ReactNode;
 21  }) {
 22    return (
 23      <div className="state-block state-empty">
 24        <span className="state-illustration" aria-hidden="true"><Icon name="workspace" size={25} /></span>
 25        <p className="state-title">{title}</p>
 26        {hint && <p className="state-hint">{hint}</p>}
 27        {actions && <div className="form-actions">{actions}</div>}
 28      </div>
 29    );
 30  }
