 32  /**
 33   * Safe API error presentation: a sentence the reader can act on, with the
 34   * documented error code kept underneath for support. Stack traces never
 35   * reach this component.
 36   *
 37   * The code used to lead the line, which meant the first thing a reader met
 38   * was `REQUEST_FAILED`. It is still shown — it is what you quote in a bug
 39   * report — but it no longer stands in for an explanation.
 40   */
 41  export function ErrorState({
 42    code,
 43    message,
 44    hint,
 45    onRetry,
 46  }: {
 47    code: string;
 48    message: string;
 49    hint?: string;
 50    onRetry?: () => void;
 51  }) {
 52    const { t, errorText } = useI18n();
 53    return (
 54      <div className="state-block state-error" role="alert">
 55        <p className="state-title">{errorText(code, message)}</p>
 56        {hint && <p className="state-hint">{hint}</p>}
 57        <p className="state-hint error-code-line">
 58          {t("errors.codeLabel")} <code className="state-code">{code}</code>
 59        </p>
 60        {onRetry && (
 61          <button type="button" className="button button-ghost" onClick={onRetry}>
 62            {t("common.retry")}
 63          </button>
 64        )}
 65      </div>
 66    );
 67  }
