 69  /**
 70   * One-line error for forms and panels, where a full block would push the
 71   * control the reader is trying to fix off the screen. Same localization
 72   * rule as {@link ErrorState}: sentence first, code alongside.
 73   */
 74  export function InlineError({
 75    error,
 76    fallback,
 77  }: {
 78    error: ApiError | null | undefined;
 79    fallback?: string;
 80  }) {
 81    const { errorText } = useI18n();
 82    if (!error) return null;
 83    return (
 84      <p className="inline-error" role="alert">
 85        {errorText(error.code, error.message || fallback || "")}
 86        <code className="state-code">{error.code}</code>
 87      </p>
 88    );
 89  }
