 91  /** Structured section-level loading placeholder (no full-page blocking). */
 92  export function LoadingState({ label }: { label?: string }) {
 93    const { t } = useI18n();
 94    return (
 95      <div className="state-block state-loading" role="status" aria-live="polite">
 96        <span className="loading-bar" aria-hidden="true" />
 97        <span>{label ?? t("common.loading")}</span>
 98      </div>
 99    );
100  }
