102  /**
103   * Rendered by workspace-scoped pages when the signed-in user has no
104   * active workspace selected. Opening the selector loads the page in
105   * place; if the account has no workspace yet, onboarding is offered.
106   */
107  export function SessionRequired({ contextKey }: { contextKey?: MessageKey }) {
108    const { t } = useI18n();
109    const { openPanel, workspaces, tenancyLoading } = useFrontendSession();
110    const context = contextKey ? t(contextKey) : undefined;
111  
112    if (tenancyLoading) return <LoadingState />;
113  
114    if (workspaces.length === 0) {
115      return (
116        <div className="state-block state-session">
117          <p className="state-title">{t("workspace.noWorkspaces")}</p>
118          <p className="state-hint">{t("workspace.noWorkspacesHint")}</p>
119          <Link className="button button-primary" href="/settings">
120            {t("workspace.createWorkspace")}
121          </Link>
122        </div>
123      );
124    }
125  
126    return (
127      <div className="state-block state-session">
128        <p className="state-title">{t("session.requiredTitle")}</p>
129        <p className="state-hint">{t("session.requiredHint", { context: context ?? "" })}</p>
130        <button type="button" className="button button-primary" onClick={openPanel}>
131          {t("session.configure")}
132        </button>
133      </div>
134    );
135  }
