137  export function Panel({
138    title,
139    eyebrow,
140    actions,
141    children,
142    ariaLabel,
143  }: {
144    title?: string;
145    eyebrow?: string;
146    actions?: ReactNode;
147    children?: ReactNode;
148    ariaLabel?: string;
149  }) {
150    const hasHeading = Boolean(title || eyebrow);
151    const label = ariaLabel ?? title;
152    return (
153      <section className="panel" aria-label={label}>
154        {(hasHeading || actions) && (
155          <div className="panel-heading">
156            {hasHeading && (
157              <div>
158                {eyebrow && <p className="eyebrow">{eyebrow}</p>}
159                {title && <h2>{title}</h2>}
160              </div>
161            )}
162            {actions && <div className="panel-actions">{actions}</div>}
163          </div>
164        )}
165        {children}
166      </section>
167    );
168  }
